INSERT INTO opportunities (id, company, position, source, sent_at, kind, contract, location, remote, team, salary, duration, start_date, link, description, stage, reason, notes) VALUES
(1, 'Airbus Commercial Aircraft', 'Ingénieur Principal Calculs Aérostructures & Tolérance aux Dommages', 'job_ad', '2026-10-14T09:15', 'end_client', 'cdi', 'Toulouse (Saint-Martin)', 'hybrid', 'Bureau d''études Caisson Central & Voilure (18 ingénieurs, Nastran / Patran / HyperWorks).', '68 k€', 'CDI', 'Janvier 2027', 'https://airbus.com/careers/aerostructures-lead', 'Justification statique, fatigue et tolérance aux dommages des structures primaires hybrides métal/composite (A350F et évolutions A321XLR). Support aux dérogations FAL et suivi des essais de certification CS-25.', 'in_progress', '', 'Processus très bien engagé. Excellent retour sur l''entretien technique. Le poste offre une trajectoire claire vers le statut Senior Expert.'),
(2, 'Safran Aircraft Engines', 'Architecte Intégration Nacelle & Inverseur de Poussée', 'network', '2026-10-20T14:00', 'end_client', 'cdi', 'Villaroche (77)', 'hybrid', 'Plateau programme LEAP & démonstrateur RISE Open Fan (25 ingénieurs).', '66 k€', 'CDI', 'ASAP', 'https://safran-group.com/fr/offres/integration-propulsive', 'Pilotage technique de l''interface moteur/avion, gestion des contraintes thermomécaniques, acoustiques et aérodynamiques externes des nacelles de nouvelle génération.', 'in_progress', '', 'Opportunité créée suite aux échanges avec Claire Chapuis. Défis techniques majeurs autour de l''architecture non carénée Open Fan.'),
(3, 'Dassault Aviation', 'Ingénieur Aérodynamique & Mécanique du Vol', 'inbound', '2026-10-26T11:30', 'end_client', 'cdi', 'Saint-Cloud (92)', 'onsite', 'Direction Générale Technique — Département Aérodynamique (calculs CFD Elsa & soufflerie).', '64 k€', 'CDI', 'Février 2027', 'https://dassault-aviation.com/fr/carriere', 'Développement des bases de données aérodynamiques et identification des coefficients pour les lois de commandes de vol numériques (Falcon 10X et programmes défense).', 'in_progress', '', 'Approché directement par Sophie Lemaire. Présentiel requis mais très forte valeur ajoutée technique en bureau d''études central.'),
(4, 'Thales Avionics', 'Architecte Systèmes Embarqués & Commandes de Vol (ARP4754A)', 'network', '2026-10-29T18:10', 'end_client', 'cdi', 'Mérignac (33)', 'hybrid', 'Ligne de produit Cockpits & Calculateurs critiques (12 personnes).', '60 k€', 'CDI', 'Mars 2027', 'https://thalesgroup.com/careers/avionics-sys', 'Spécification système, analyse de sécurité fonctionnelle (FHA, PSSA, SSA) et validation sur banc d''intégration Iron Bird selon ARP4754A et DO-178C.', 'applied', '', 'Candidature soumise par cooptation interne via Julien Lefèvre.'),
(5, 'Airbus Atlantic (Stelia)', 'Expert Industrialisation Composites Thermoplastiques', 'inbound', '2026-11-01T10:00', 'esn', 'freelance', 'Rochefort / Toulouse', 'hybrid', 'Équipe R&T Procédés Avancés (8 personnes).', '640 €/j', '12 mois renouv.', 'Décembre 2026', 'https://airbus-atlantic.com/projets', 'Mise au point des procédés de drapage automatisé (AFP) et consolidation in-situ pour panneaux de fuselage en composites thermoplastiques.', 'applied', '', 'Mission présentée par Marc Vasseur (AeroTalents Executive). TJM validé côté cabinet.'),
(6, 'ATR Aircraft', 'Ingénieur Essais en Vol & Performances Avion', 'job_ad', '2026-11-02T09:30', 'end_client', 'cdi', 'Blagnac (31)', 'hybrid', 'Direction des Essais en Vol (9 ingénieurs).', '59 k€', 'CDI', 'Printemps 2027', 'https://atr-aircraft.com/careers', 'Préparation des campagnes d''essais en vol, dépouillement télémesure temps réel et mise à jour des manuels de performances opérationnelles (ATR 72-600F et moteurs PW127XT).', 'applied', '', 'Poste très opérationnel avec présence sur le tarmac et en salle d''écoute télémesure.'),
(7, 'Latécoère', 'Référent Technique Structures Portes Passagers & Cargo', 'spontaneous', '', 'end_client', 'cdi', 'Toulouse (Périole)', 'hybrid', 'Bureau d''Études Aérostructures.', '62 k€', 'CDI', 'Premier trimestre 2027', 'https://latecoere.aero/carrieres', 'Conception et justification des mécanismes de verrouillage et de la structure primaire des portes composites.', 'to_contact', '', 'Préparer une prise de contact directe auprès de Laurent Bénézech.'),
(8, 'Daher Aerospace', 'Architecte Intégration Systèmes Propulsion Hybride-Électrique', 'network', '', 'end_client', 'cdi', 'Tarbes (65)', 'hybrid', 'Équipe Démonstrateur Décarbonation (15 personnes).', '63 k€', 'CDI', 'Février 2027', 'https://daher.com/fr/rejoindre-daher', 'Intégration mécanique et thermique des turbogénérateurs et des packs batteries haute tension sur cellule TBM.', 'to_contact', '', 'Sujet évoqué par Philippe Gauthier. Attendre son feu vert avant d''envoyer le dossier officiel.'),
(9, 'Liebherr-Aerospace', 'Chef de Projet Qualification Systèmes de Conditionnement d''Air', 'spontaneous', '2026-09-12T08:45', 'end_client', 'cdi', 'Toulouse (31)', 'hybrid', 'Centre d''essais environnementaux et vibratoires (10 ingénieurs et techniciens).', '66 k€', 'CDI', 'Immédiat', 'https://liebherr.com/aerospace-toulouse', 'Pilotage des campagnes de qualification DO-160G (froid, chaud, altitude, vibrations, foudre) sur les systèmes de prélèvement d''air et de pressurisation.', 'won', '', 'Proposition d''embauche écrite reçue à 66 k€ fixe + intéressement/participation élevé. Délai de réponse jusqu''au 20 novembre.'),
(10, 'ArianeGroup', 'Ingénieur Turbopompes & Propulsion Cryogénique', 'job_ad', '2026-09-18T16:20', 'end_client', 'cdi', 'Vernon (27)', 'onsite', 'Département Propulsion Liquide (programme Prometheus / Ariane 6).', '55 k€', 'CDI', 'Janvier 2027', 'https://ariane.group/careers/propulsion', 'Analyse dynamique des rotors haute vitesse et tenue mécanique des roulements en ambiance hydrogène et oxygène liquide.', 'declined', 'Package salarial plafonné à 55 k€ et localisation à Vernon sans possibilité de télétravail régulier.', 'Sujet technique passionnant sur le moteur réutilisable Prometheus, mais les conditions contractuelles et géographiques ne s''alignaient pas.'),
(11, 'Collins Aerospace', 'Lead Engineer Systèmes de Trains d''Atterrissage', 'job_ad', '2026-09-25T13:00', 'end_client', 'cdi', 'Toulouse (Colomiers)', 'hybrid', 'Antenne Ingénierie Systèmes Mécaniques.', '63 k€', 'CDI', 'ASAP', 'https://collinsaerospace.com/careers', 'Coordination technique des actionneurs hydromécaniques et électriques d''extension/rétraction et d''orientation.', 'rejected', 'Gel budgétaire annoncé par la maison-mère américaine en cours de processus de recrutement.', 'Le manager opérationnel a confirmé que mon profil était retenu en short-list finale avant la suspension du poste.');
